effective_config_excerpt.upstream:
upstream transporte {
    zone transporte 64k;
    server 127.0.0.1:58306 resolve max_fails=1 fail_timeout=2s;
    server 127.0.0.1:58370 resolve max_fails=1 fail_timeout=2s;
    keepalive 8;
  }

effective_config_excerpt.public_ws_location:
location /services/transporte/ws/v1/tracking/ {
      proxy_pass http://transporte/ws/v1/tracking/;
      proxy_http_version 1.1;
      proxy_set_header Upgrade $http_upgrade;
      proxy_set_header Connection "upgrade";
      proxy_set_header Host 127.0.0.1:58305;
      proxy_set_header X-Forwarded-Proto https;
      proxy_set_header X-Forwarded-For $remote_addr;
      proxy_set_header X-Forwarded-Host "";
      proxy_set_header X-Forwarded-Prefix "";
      proxy_set_header X-Forwarded-Port "";
      proxy_set_header X-Forwarded-By "";
      proxy_set_header Forwarded "";
      proxy_read_timeout 75s;
      proxy_send_timeout 10s;
      proxy_buffering off;
    }
